/**
 * Scale a percentage rect to a pixel rect on a concrete image (D-01: every
 * device renders the same layout proportionally). Round, then clamp: x/y land
 * within [0, dim-1]; w/h stay at least 1 and never run past the image edge.
 */
export function rectToPixels(rect: PctRect, imgW: number, imgH: number): { x: number; y: number; w: number; h: number } {
  const x = clamp(Math.round(rect.x * imgW), 0, Math.max(0, imgW - 1))
  const y = clamp(Math.round(rect.y * imgH), 0, Math.max(0, imgH - 1))
  const w = clamp(Math.round(rect.w * imgW), 1, Math.max(1, imgW - x))
  const h = clamp(Math.round(rect.h * imgH), 1, Math.max(1, imgH - y))
  return { x, y, w, h }
}

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(Math.max(n, lo), hi)
}
